alter table "public"."deals" add column "status" text not null default 'potential'::text;

-- Migrate the old pipeline into the new Sandler model: stage becomes the
-- methodology phase (visible on active deals) and status drives the board.
update public.deals set
    status = case stage when 'won' then 'won' when 'lost' then 'exited' else 'active' end,
    stage = case stage
        when 'proposal-sent' then 'solution'
        when 'in-negociation' then 'solution'
        when 'won' then 'solution'
        else 'contact'
    end;


alter table "public"."deals" add column "fts" tsvector generated always as (
    public.search_document(name, description, deal_type, stage, status, decision_process)
) stored;

